/**
 * Response helpers for the Pages Functions.
 *
 * Note: public/_headers does NOT apply to responses generated by Functions,
 * so every response built here sets the security headers itself. The pages
 * built here contain no scripts at all, so their policy allows none.
 */
import type { Env } from './env';
import { getDictionary, type Dictionary } from '../src/i18n/dictionaries';
import type { Locale } from '../src/i18n/locales';

export const SECURITY_HEADERS: Record<string, string> = {
  'Content-Security-Policy':
    "default-src 'self'; script-src 'none'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; frame-src 'none'; connect-src 'self'; form-action 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'",
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), interest-cohort=()',
  'Cross-Origin-Opener-Policy': 'same-origin',
};

function withSecurity(headers: HeadersInit = {}): Headers {
  const h = new Headers(headers);
  for (const [k, v] of Object.entries(SECURITY_HEADERS)) if (!h.has(k)) h.set(k, v);
  return h;
}

export function json(data: unknown, status = 200, headers: HeadersInit = {}): Response {
  const h = withSecurity(headers);
  h.set('Content-Type', 'application/json; charset=utf-8');
  if (!h.has('Cache-Control')) h.set('Cache-Control', 'no-store');
  return new Response(JSON.stringify(data), { status, headers: h });
}

export function redirect(location: string, status = 302, headers: HeadersInit = {}): Response {
  const h = withSecurity(headers);
  h.set('Location', location);
  return new Response(null, { status, headers: h });
}

/** True when the request comes from our own JavaScript (fetch with Accept: application/json). */
export function wantsJson(request: Request): boolean {
  return (request.headers.get('Accept') || '').includes('application/json');
}

/**
 * Basic CSRF protection: form posts must come from our own site.
 * Accepts the configured public origin and the request's own origin
 * (so preview deployments on *.pages.dev keep working).
 */
export function isSameOrigin(request: Request, env: Env): boolean {
  const allowed = new Set([new URL(request.url).origin, env.SITE_ORIGIN].filter(Boolean));
  const origin = request.headers.get('Origin');
  if (origin) return allowed.has(origin);
  // Very old browsers send no Origin header; fall back to Fetch Metadata if present.
  const site = request.headers.get('Sec-Fetch-Site');
  return !site || site === 'same-origin' || site === 'none';
}

/** Reject oversized bodies before parsing them. */
export function bodyTooLarge(request: Request, maxBytes = 16 * 1024): boolean {
  const length = Number(request.headers.get('Content-Length') || 0);
  return length > maxBytes;
}

export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
}

interface PageOptions {
  lang: Locale;
  title: string;
  /** Trusted HTML — escape every user- or dictionary-derived value with escapeHtml(). */
  bodyHtml: string;
  status?: number;
}

/**
 * A small, self-contained HTML page used when the visitor has no JavaScript
 * (the form posted natively). Styled inline to match the site's colours.
 */
export function htmlPage({ lang, title, bodyHtml, status = 200 }: PageOptions): Response {
  const t: Dictionary = getDictionary(lang);
  const html = `<!doctype html>
<html lang="${lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>${escapeHtml(title)} | ${escapeHtml(t.meta.siteName)}</title>
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<style>
  :root { color-scheme: light dark; --ink: #161b26; --head: #12203f; --muted: #475569; --bg: #f8f6f1; --panel: #fff; --rule: #d6cfc1; --btn-bg: #1b2c52; --btn-fg: #fff; --focus: #2f4a85; }
  @media (prefers-color-scheme: dark) { :root { --ink: #e2e8f0; --head: #fff; --muted: #94a3b8; --bg: #0b142a; --panel: #12203f; --rule: #1b2c52; --btn-bg: #f8f6f1; --btn-fg: #0b142a; --focus: #f5c84c; } }
  * { box-sizing: border-box; }
  body { margin: 0; font: 17px/1.65 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; color: var(--ink); background: var(--bg); }
  header { border-top: 4px solid #1b2c52; border-bottom: 1px solid var(--rule); padding: 18px 16px; }
  header a { font: 600 1.1rem/1.2 "Iowan Old Style", "Palatino Linotype", Georgia, serif; color: var(--head); text-decoration: none; }
  main { max-width: 40rem; margin: 0 auto; padding: 48px 16px 72px; }
  h1 { font: 600 2.1rem/1.15 "Iowan Old Style", "Palatino Linotype", Georgia, serif; color: var(--head); margin: 0 0 20px; text-wrap: balance; }
  .box { background: var(--panel); border: 1px solid var(--rule); border-top: 4px solid var(--btn-bg); padding: 24px; margin: 28px 0; }
  .notice { border-top-color: #e6b325; }
  .code { display: inline-block; font: 700 1.4rem/1 ui-monospace, monospace; letter-spacing: .08em; padding: 12px 16px; background: var(--bg); border: 1px solid var(--rule); user-select: all; }
  .muted { color: var(--muted); font-size: .95rem; }
  .btn { display: inline-flex; align-items: center; min-height: 44px; background: var(--btn-bg); color: var(--btn-fg); border: 1px solid transparent; padding: 10px 20px; border-radius: 3px; text-decoration: none; font-weight: 600; margin: 8px 8px 0 0; }
  a { color: inherit; text-underline-offset: .2em; }
  :focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
</style>
</head>
<body>
<header><a href="/${lang}/">${escapeHtml(t.meta.siteName)}</a></header>
<main>
<h1>${escapeHtml(title)}</h1>
${bodyHtml}
</main>
</body>
</html>`;
  const headers = withSecurity({ 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  return new Response(html, { status, headers });
}

export const p = (text: string, cls = '') => `<p${cls ? ` class="${cls}"` : ''}>${escapeHtml(text)}</p>`;
export const button = (href: string, label: string) => `<a class="btn" href="${escapeHtml(href)}">${escapeHtml(label)}</a>`;
